import re
from .exceptions import InvalidAlarm


class Alarm(object):
    """ Represents plain alarm in alarms_watchdog. Used to detect alarms in active alarms on BTS. """

    def __init__(self, alarm_id=None, fault_id=None, fault_name=None, hw_path=None, severity=None, reason=None,
                 unit_path=None, impacted_cells_count=None, fault_signature=None):
        """
        Sets alarm's parameters.

        :param alarm_id: used during comparison with alarm ID of active alarms; defaults to None (not used)
        :type alarm_id: str or None
        :param fault_id: used during comparison with fault ID of active alarms; defaults to None (not used)
        :type fault_id: str or None
        :param fault_name: used during comparison with fault name of active alarms; defaults to None (not used)
        :type fault_name: str or None
        :param hw_path: used during comparison with HW path of active alarms;
                        can be used only for ClassicalBts and RealEnb, unavailable for CloudBts;
                        defaults to None (not used)
        :type hw_path: str, re.Pattern or None
        :param severity: used during comparison with severity of active alarms; defaults to None (not used)
        :type severity: str or None
        :param reason: used during comparison with reason of active alarms;
                       can be used only for ClassicalBts and RealEnb, unavailable for CloudBts;
                       defaults to None (not used)
        :type reason: str, re.Pattern or None
        :raises InvalidAlarm: when all of alarm's parameters will be None
        :param unit_path: used during comparison with unit path of active alarms; defaults to None (not used)
        :type unit_path: str, re.Pattern or None
        :param impacted_cells_count: used during comparison with impacted cells count of active alarms;
                                     can be used only for ClassicalBts and RealEnb, unavailable for CloudBts;
                                     defaults to None (not used)
        :type impacted_cells_count: str or None
        :param fault_signature: used during comparison with fault signature of active alarms;
                                comparison will take into account only provided attributes of fault signature;
                                can be used only for ClassicalBts and RealEnb, unavailable for CloudBts;
                                defaults to None (not used)
        :type fault_signature: dict or None
        """
        self._validate_data(alarm_id, fault_id, fault_name, hw_path, severity, reason, unit_path, impacted_cells_count,
                            fault_signature)
        self._alarm_id = str(alarm_id) if alarm_id is not None else alarm_id
        self._fault_id = str(fault_id) if fault_id is not None else fault_id
        self._fault_name = fault_name
        self._hw_path = hw_path
        self._severity = severity
        self._reason = reason
        self._unit_path = unit_path
        self._impacted_cells_count = impacted_cells_count
        self._fault_signature = fault_signature

    @property
    def alarm_id(self):
        """
        Used during comparison with alarm ID of active alarms.

        :return: alarm ID
        :rtype str or None
        """
        return self._alarm_id

    @property
    def fault_id(self):
        """
        Used during comparison with fault ID of active alarms.

        :return: fault ID
        :rtype str or None
        """
        return self._fault_id

    @property
    def fault_name(self):
        """
        Used during comparison with fault name of active alarms.

        :return: fault name
        :rtype str or None
        """
        return self._fault_name

    @property
    def hw_path(self):
        """
        Used during comparison with HW path of active alarms.

        :return: HW path
        :rtype str or None
        """
        return self._hw_path

    @property
    def severity(self):
        """
        Used during comparison with severity of active alarms.

        :return: severity
        :rtype str or None
        """
        return self._severity

    @property
    def reason(self):
        """
        Used during comparison with reason of active alarms.

        :return: reason
        :rtype str or None
        """
        return self._reason

    @property
    def unit_path(self):
        """
        Used during comparison with unit path of active alarms.

        :return: unit path
        :rtype str or None
        """
        return self._unit_path

    @property
    def impacted_cells_count(self):
        """
        Used during comparison with impacted cells count of active alarms.

        :return: Impacted cells count
        :rtype str or None
        """
        return self._impacted_cells_count

    @property
    def fault_signature(self):
        """
        Used during comparison with fault signature of active alarms; comparison will take
        into account only provided attributes of fault signature.

        :return: fault signature
        :rtype dict or None
        """
        return self._fault_signature

    def matches_exactly(self, other):
        """
        Checks whether two alarms are equal by comparing values of all their attributes.
        :param other: alarm to be compared with this alarm
        :type other: Alarm
        :return: True if all attributes of both alarms have equal values, False otherwise (or if other is not an Alarm)
        :rtype: bool
        """
        if not isinstance(other, self.__class__):
            return False

        return self.alarm_id == other.alarm_id and \
            self.fault_id == other.fault_id and \
            self.fault_name == other.fault_name and \
            self.hw_path == other.hw_path and \
            self.severity == other.severity and \
            self.reason == other.reason and \
            self.unit_path == other.unit_path and \
            self.impacted_cells_count == other.impacted_cells_count and \
            self.fault_signature == other.fault_signature

    @staticmethod
    def _validate_data(*attributes):
        if all(attribute is None for attribute in attributes):
            raise InvalidAlarm("Alarm must have at least one attribute which is not None")

    def __eq__(self, other):
        if not isinstance(other, self.__class__):
            return False

        partial_equalities = self.__get_partial_equalities(other)

        if not partial_equalities:
            return False

        return all(partial_equalities)

    def __ne__(self, other):
        return not self.__eq__(other)

    def __repr__(self):
        return 'Alarm(alarm_id={}, fault_id={}, fault_name={}, hw_path={}, severity={}, reason={}, ' \
               'unit_path={}, impacted_cells_count={}, fault_signature={})'.format(
                   self._alarm_id,
                   self._fault_id,
                   self._fault_name,
                   self._hw_path,
                   self._severity,
                   self._reason,
                   self._unit_path,
                   self._impacted_cells_count,
                   self._fault_signature)

    def __get_partial_equalities(self, other):
        partial_equalities = []

        self.__add_alarm_id_equality(partial_equalities, other.alarm_id)
        self.__add_fault_id_equality(partial_equalities, other.fault_id)
        self.__add_fault_name_equality(partial_equalities, other.fault_name)
        self.__add_hw_path_equality(partial_equalities, other.hw_path)
        self.__add_severity_equality(partial_equalities, other.severity)
        self.__add_reason_equality(partial_equalities, other.reason)
        self.__add_unit_path_equality(partial_equalities, other.unit_path)
        self.__add_impacted_cells_count(partial_equalities, other.impacted_cells_count)
        self.__add_fault_signature_equality(partial_equalities, other.fault_signature)

        return partial_equalities

    def __add_alarm_id_equality(self, equalities, other_alarm_id):
        if self.alarm_id is not None and other_alarm_id is not None:
            equalities.append(self.alarm_id == other_alarm_id)

    def __add_fault_id_equality(self, equalities, other_fault_id):
        if self.fault_id is not None and other_fault_id is not None:
            equalities.append(self.fault_id == other_fault_id)

    def __add_fault_name_equality(self, equalities, other_fault_name):
        if self.fault_name is not None and other_fault_name is not None:
            equalities.append(self.fault_name == other_fault_name)

    def __add_hw_path_equality(self, equalities, other_hw_path):
        if self.hw_path is not None and other_hw_path is not None:
            self.__compare_string_or_regex(equalities, self.hw_path, other_hw_path)

    def __add_severity_equality(self, equalities, other_severity):
        if self.severity is not None and other_severity is not None:
            equalities.append(self.severity == other_severity)

    def __add_reason_equality(self, equalities, other_reason):
        if self.reason is not None and other_reason is not None:
            self.__compare_string_or_regex(equalities, self.reason, other_reason)

    def __add_unit_path_equality(self, equalities, other_unit_path):
        if self.unit_path is not None and other_unit_path is not None:
            self.__compare_string_or_regex(equalities, self.unit_path, other_unit_path)

    def __add_impacted_cells_count(self, equalities, other_impacted_cells_count):
        if self.impacted_cells_count is not None and other_impacted_cells_count is not None:
            equalities.append(self.impacted_cells_count == other_impacted_cells_count)

    def __add_fault_signature_equality(self, equalities, other_fault_signature):
        if self.fault_signature is not None and other_fault_signature is not None:
            self.__compare_fault_signatures(equalities, other_fault_signature)

    @staticmethod
    def __compare_string_or_regex(equalities, first, other):
        _re_pattern_class = type(re.compile(''))

        if isinstance(first, _re_pattern_class) and isinstance(other, _re_pattern_class):
            equalities.append(first == other)
        elif isinstance(other, _re_pattern_class):
            equalities.append(other.search(first))
        elif isinstance(first, _re_pattern_class):
            equalities.append(first.search(other))
        else:
            equalities.append(first == other)

    def __compare_fault_signatures(self, equalities, other_fault_signature):
        for key, value in other_fault_signature.items():
            try:
                equalities.append(value == self.fault_signature[key])
            except KeyError:
                continue


class DetectedAlarm(Alarm):
    """ Represents detected alarm in alarms_watchdog. Used to log alarm detection in watch history. """

    def __init__(self, detection_time, alarm_id, fault_id, fault_name, hw_path, severity=None, reason=None,
                 unit_path=None, impacted_cells_count=None, fault_signature=None):
        super(DetectedAlarm, self).__init__(alarm_id, fault_id, fault_name, hw_path, severity, reason,
                                            unit_path, impacted_cells_count, fault_signature)
        self._detection_time = detection_time

    @property
    def time(self):
        return self._detection_time

    def __str__(self):
        return '{} DETECTED fault_name: {}, severity: {}, alarm_id: {}, fault_id: {}, hw_path: {}, reason: {}, ' \
               'unit_path: {}, impacted_cells_count: {}, fault_signature: {}'.format(
                   self._detection_time,
                   self._fault_name,
                   self._severity,
                   self._alarm_id,
                   self._fault_id,
                   self._hw_path,
                   self._reason,
                   self._unit_path,
                   self._impacted_cells_count,
                   self._fault_signature)

    def __repr__(self):
        template = 'DetectedAlarm(detection_time={}, alarm_id={}, fault_id={}, fault_name={}, ' \
                   'hw_path={}, severity={}, reason={}, unit_path={}, impacted_cells_count={}, fault_signature={})'
        return template.format(
            self.time, self._alarm_id, self._fault_id, self._fault_name, self._hw_path, self._severity, self._reason,
            self._unit_path, self._impacted_cells_count, self._fault_signature)


class LostAlarm(Alarm):
    """ Represents lost alarm in alarms_watchdog. Used to log alarm loss in watch history. """

    def __init__(self, loss_time, alarm_id, fault_id, fault_name, hw_path, severity=None, reason=None,
                 unit_path=None, impacted_cells_count=None, fault_signature=None):
        super(LostAlarm, self).__init__(alarm_id, fault_id, fault_name, hw_path, severity, reason,
                                        unit_path, impacted_cells_count, fault_signature)
        self._loss_time = loss_time

    @property
    def time(self):
        return self._loss_time

    def __str__(self):
        return '{} LOST     fault_name: {}, severity: {}, alarm_id: {}, fault_id: {}, hw_path: {}, reason: {}, ' \
               'unit_path: {}, impacted_cells_count: {}, fault_signature: {}'.format(
                   self._loss_time,
                   self._fault_name,
                   self._severity,
                   self._alarm_id,
                   self._fault_id,
                   self._hw_path,
                   self._reason,
                   self._unit_path,
                   self._impacted_cells_count,
                   self._fault_signature)

    def __repr__(self):
        template = \
            'LostAlarm(loss_time={}, alarm_id={}, fault_id={}, fault_name={}, hw_path={}, severity={}, reason={}, ' \
            'unit_path={}, impacted_cells_count={}, fault_signature={})'
        return template.format(
            self.time, self._alarm_id, self._fault_id, self._fault_name, self._hw_path, self._severity, self._reason,
            self._unit_path, self._impacted_cells_count, self._fault_signature)
